import{_ as s,a0 as u,w as r,s as i,ao as d,I as o,x as t,a1 as l,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"为何我们需要一个开放模型来设计评估公共政策 | LCTT x X-CMD","titleTemplate":false,"description":"为何我们需要一个开放模型来设计评估公共政策 | LCTT (201705) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"为何我们需要一个开放模型来设计评估公共政策 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"为何我们需要一个开放模型来设计评估公共政策 | LCTT (201705) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201705/20170110 Why we need an open model to design and evaluate public policy","title":"为何我们需要一个开放模型来设计评估公共政策","tag":"201705","desc":""},"relativePath":"201705/20170110 Why we need an open model to design and evaluate public policy.md","filePath":"[post].md"}'),a={name:"201705/20170110 Why we need an open model to design and evaluate public policy.md"};function m(f,e,g,y,b,T){const p=u("Link");return r(),i("div",null,[e[18]||(e[18]=d('<h1 id="为何我们需要一个开放模型来设计评估公共政策" tabindex="-1">为何我们需要一个开放模型来设计评估公共政策 <a class="header-anchor" href="#为何我们需要一个开放模型来设计评估公共政策" aria-label="Permalink to “为何我们需要一个开放模型来设计评估公共政策”">​</a></h1><blockquote><p>想象一个 app 可以让市民来试车提出的政策。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/government/GOV_citizen_participation.jpg?itok=eeLWQgev" alt="Why we need an open model to design and evaluate public policy" title="Why we need an open model to design and evaluate public policy"></p><p>图片提供：opensource.com</p><p>在政治选举之前的几个月中，公众辩论会加剧，并且公民面临大量的各种政策选择的信息。在数据驱动的社会中，新的见解一直在为决策提供信息，对这些信息的深入了解从未如此重要，但公众仍然没有意识到为公共政策建模的全部潜力。</p><p>在“<ruby>开放政府<rt>open government</rt></ruby>”的概念不断演变以跟上新技术进步的时代，政府的政策模型和分析可能是新一代的开放知识。</p><p>政府开源模型 （GOSM） 是指政府开发的模型，其目的是设计和评估政策，免费提供给所有人使用、分发、不受限制地修改。社区可以提高政策建模的质量、可靠性和准确性，创造有利于公众的新的数据驱动程序。</p><p>今天的这一代人与技术相互作用，这俨然成为了它的第二种本质，自然而然地吸收了大量的信息。如果我们可以在使用 GOSM 在虚拟、沉浸式环境中与不同的公共政策进行互动那会如何？</p><p>想象一下如果有一个程序，允许公民试车提出的政策来确定他们想要生活的未来。他们会本能地学习关键的驱动因素和所需要的东西。不久之后，公众将更深入地了解公共政策的影响，并更加精明地引导有争议性的公众辩论。</p><p>为什么我们以前没有更好的使用这些模型？原因在于公共政策建模的神秘面纱。</p><p>在一个如我们所生活的复杂的社会中，量化政策影响是一项艰巨的任务，并被被描述为一种“美好艺术”。此外，大多数政府政策模型都是基于行政和其他私人持有的数据。然而，政策分析师为了指导政策设计而勇于追求，多次以大量武力而赢得政治斗争的胜利。</p><p>数字是很有说服力的。它们构建可信度，并常常被用作引入新政策的理由。公共政策模型的发展赋予政治家和官僚权力，这些政治家和官僚们可能不愿意破坏现状。给予这一点可能并不容易，但 GOSM 为前所未有的公共政策改革提供了机会。</p><p>GOSM 将所有人的竞争环境均衡化：政治家、媒体、游说团体、利益相关者和公众。通过向社区开放政策评估的大门, 政府可以在公共领域为创造、创新和效率引入新的和未发现的能力。但在公共政策设计中，利益相关者和政府之间战略互动有哪些实际影响？</p><p>GOSM 是独一无二的，因为它们主要是设计公共政策的工具，而不一定需要重新分配私人收益。利益相关者和游说团体可能会将 GOSM 与其私人信息一起使用，以获得对经济参与者私人利益的政策环境运作的新见解。</p><p>GOSM 可以成为利益相关者在公共辩论中保持权力平衡的武器，并为战略争取最佳利益么？</p><p>作为一个可变的公共资源，GOSM 在概念上由纳税人资助，并属于国家。私有实体在不向社会带来利益的情况下从 GOSM 中获得资源是合乎道德的吗？与可能用于更有效的服务提供的那些程序不同，替代政策建议更有可能由咨询机构使用，并有助于公众辩论。</p><p>开源社区经常使用 “copyleft 许可证” 来确保代码和在此许可证下的任何衍生作品对所有人都开放。当产品价值是代码本身，这需要重新分配才能获得最大利益，它需要重新分发来获得最大的利益。但是，如果代码或 GOSM 重新分发是主要产品附带的，那它会是对现有政策环境的新战略洞察么？</p><p>在私人收集的数据变得越来越多的时候，GOSM 背后的真正价值可能是底层数据，它可以用来改进模型本身。最终，政府是唯一有权实施政策的消费者，利益相关者可以选择在谈判中分享修改后的 GOSM。</p><p>政府在公开发布政策模型时面临的巨大挑战是提高透明度的同时保护隐私。理想情况下，发布 GOSM 将需要以保护建模关键特征的方式保护封闭的数据。</p><p>公开发布 GOSM 通过促进市民对民主的更多了解和参与，使公民获得权力，从而改善政策成果和提高公众满意度。在开放的政府乌托邦中，开放的公共政策发展将是政府和社区之间的合作性努力，这里知识、数据和分析可供大家免费使用。</p>',20)),o("p",null,[o("em",null,[e[2]||(e[2]=t("在霍巴特举行的 linux.conf.au 2017（",-1)),l(p,{href:"https://twitter.com/search?q=%23lca2017&src=typd"},{default:n(()=>[...e[0]||(e[0]=[t("＃lca2017",-1)])]),_:1}),e[3]||(e[3]=t("）了解更多 Audrey Lobo-Pulo 的讲话：",-1)),l(p,{href:"https://linux.conf.au/schedule/presentation/31/"},{default:n(()=>[...e[1]||(e[1]=[t("公开发布的政府模型",-1)])]),_:1}),e[4]||(e[4]=t("。",-1))])]),e[19]||(e[19]=o("p",null,[o("em",null,"声明：本文中提出的观点属于 Audrey Lobo-Pulo，不一定是澳大利亚政府的观点。")],-1)),e[20]||(e[20]=o("hr",null,null,-1)),e[21]||(e[21]=o("p",null,"作者简介：",-1)),e[22]||(e[22]=o("p",null,[o("img",{src:"https://opensource.com/sites/default/files/styles/profile_pictures/public/pictures/1-_mg_2552.jpg?itok=-RflZ4Wv",alt:""})],-1)),e[23]||(e[23]=o("p",null,"Audrey Lobo-Pulo - Audrey Lobo-Pulo 博士是 Phoensight 的联合创始人，并且开放政府以及政府建模开源软件的倡导者。一位物理学家，在加入澳大利亚公共服务部后，她转而从事经济政策建模工作。Audrey 参与了各种经济政策选择的建模，目前对政府开放数据和开放式政策建模感兴趣。 Audrey 对政府的愿景是将数据科学纳入公共政策分析。",-1)),e[24]||(e[24]=o("hr",null,null,-1)),o("p",null,[e[6]||(e[6]=t("via: ",-1)),l(p,{href:"https://opensource.com/article/17/1/government-open-source-models"},{default:n(()=>[...e[5]||(e[5]=[t("https://opensource.com/article/17/1/government-open-source-models",-1)])]),_:1})]),o("p",null,[e[10]||(e[10]=t("作者：",-1)),l(p,{href:"https://opensource.com/users/audrey-lobo-pulo"},{default:n(()=>[...e[7]||(e[7]=[t("Audrey Lobo-Pulo",-1)])]),_:1}),e[11]||(e[11]=t(" 译者：",-1)),l(p,{href:"https://github.com/geekpi"},{default:n(()=>[...e[8]||(e[8]=[t("geekpi",-1)])]),_:1}),e[12]||(e[12]=t(" 校对：",-1)),l(p,{href:"https://github.com/wxy"},{default:n(()=>[...e[9]||(e[9]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[15]||(e[15]=t("本文由 ",-1)),l(p,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[13]||(e[13]=[t("LCTT",-1)])]),_:1}),e[16]||(e[16]=t(" 原创编译，",-1)),l(p,{href:"https://linux.cn/"},{default:n(()=>[...e[14]||(e[14]=[t("Linux中国",-1)])]),_:1}),e[17]||(e[17]=t(" 荣誉推出",-1))])])}const x=s(a,[["render",m]]);export{v as __pageData,x as default};
